{
 "json_schema": {
  "$ref": "#/definitions/EraAdjustedProps",
  "definitions": {
   "EraAdjustedProps": {
    "type": "object",
    "properties": {
     "format": {
      "type": "string",
      "enum": [
       "vertical",
       "landscape"
      ]
     },
     "hook_shape": {
      "type": "string",
      "enum": [
       "payoff-first",
       "contradiction",
       "scenario",
       "stake"
      ]
     },
     "title": {
      "type": "string",
      "maxLength": 60
     },
     "metric_raw_label": {
      "type": "string"
     },
     "metric_adjusted_label": {
      "type": "string"
     },
     "rows": {
      "type": "array",
      "items": {
       "type": "object",
       "properties": {
        "player_id": {
         "type": "string"
        },
        "name": {
         "type": "string"
        },
        "raw_rank": {
         "type": "integer",
         "exclusiveMinimum": 0
        },
        "adjusted_rank": {
         "type": "integer",
         "exclusiveMinimum": 0
        },
        "raw_value": {
         "type": "number"
        },
        "adjusted_value": {
         "type": "number"
        },
        "raw_rank_fact_key": {
         "type": "string",
         "pattern": "^[a-z0-9-]+:[^#\\s]+#[a-z_]+$"
        },
        "adjusted_rank_fact_key": {
         "$ref": "#/definitions/EraAdjustedProps/properties/rows/items/properties/raw_rank_fact_key"
        },
        "raw_fact_key": {
         "$ref": "#/definitions/EraAdjustedProps/properties/rows/items/properties/raw_rank_fact_key"
        },
        "adjusted_fact_key": {
         "$ref": "#/definitions/EraAdjustedProps/properties/rows/items/properties/raw_rank_fact_key"
        }
       },
       "required": [
        "player_id",
        "name",
        "raw_rank",
        "adjusted_rank",
        "raw_value",
        "adjusted_value",
        "raw_rank_fact_key",
        "adjusted_rank_fact_key",
        "raw_fact_key",
        "adjusted_fact_key"
       ],
       "additionalProperties": false
      },
      "minItems": 3,
      "maxItems": 12
     },
     "highlight_player_id": {
      "type": "string"
     },
     "scenes": {
      "type": "array",
      "items": {
       "type": "object",
       "properties": {
        "id": {
         "type": "string"
        },
        "kind": {
         "type": "string",
         "enum": [
          "hook",
          "context",
          "reveal",
          "payoff",
          "close",
          "endcard"
         ]
        },
        "on_screen": {
         "type": "string",
         "maxLength": 80
        },
        "focus": {
         "type": "array",
         "items": {
          "type": "string"
         },
         "default": []
        }
       },
       "required": [
        "id",
        "kind",
        "on_screen"
       ],
       "additionalProperties": false
      },
      "minItems": 3
     },
     "attribution": {
      "type": "string",
      "minLength": 1
     },
     "method_note": {
      "type": "string",
      "minLength": 1
     },
     "show_safe_zone": {
      "type": "boolean",
      "default": false
     },
     "timing": {
      "type": "object",
      "properties": {
       "duration_s": {
        "type": "number",
        "exclusiveMinimum": 0
       },
       "scenes": {
        "type": "array",
        "items": {
         "type": "object",
         "properties": {
          "scene_id": {
           "type": "string"
          },
          "start_s": {
           "type": "number"
          },
          "end_s": {
           "type": "number"
          },
          "voice_src": {
           "type": "string"
          }
         },
         "required": [
          "scene_id",
          "start_s",
          "end_s"
         ],
         "additionalProperties": false
        }
       },
       "words": {
        "type": "array",
        "items": {
         "type": "object",
         "properties": {
          "scene_id": {
           "type": "string"
          },
          "display": {
           "type": "string"
          },
          "spoken": {
           "type": "string"
          },
          "start_s": {
           "type": "number"
          },
          "end_s": {
           "type": "number"
          }
         },
         "required": [
          "scene_id",
          "display",
          "spoken",
          "start_s",
          "end_s"
         ],
         "additionalProperties": false
        }
       },
       "cues": {
        "type": "array",
        "items": {
         "type": "object",
         "properties": {
          "start_s": {
           "type": "number"
          },
          "end_s": {
           "type": "number"
          },
          "lines": {
           "type": "array",
           "items": {
            "type": "string"
           },
           "minItems": 1,
           "maxItems": 2
          },
          "words": {
           "type": "array",
           "items": {
            "$ref": "#/definitions/EraAdjustedProps/properties/timing/properties/words/items"
           }
          }
         },
         "required": [
          "start_s",
          "end_s",
          "lines",
          "words"
         ],
         "additionalProperties": false
        }
       },
       "music": {
        "type": "array",
        "items": {
         "type": "object",
         "properties": {
          "src": {
           "type": "string"
          },
          "start_s": {
           "type": "number"
          },
          "end_s": {
           "type": "number"
          },
          "gain_db": {
           "type": "number"
          }
         },
         "required": [
          "src",
          "start_s",
          "end_s",
          "gain_db"
         ],
         "additionalProperties": false
        },
        "default": []
       },
       "voice_lead_s": {
        "type": "number",
        "default": 0.5
       }
      },
      "required": [
       "duration_s",
       "scenes",
       "words",
       "cues"
      ],
      "additionalProperties": false
     }
    },
    "required": [
     "format",
     "hook_shape",
     "title",
     "metric_raw_label",
     "metric_adjusted_label",
     "rows",
     "highlight_player_id",
     "scenes",
     "attribution",
     "method_note"
    ],
    "additionalProperties": false
   }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
 },
 "rules": [
  "first scene kind must be 'hook' (its on_screen text is the hook sentence, shown at 0 s)",
  "vertical: last scene kind must be 'close' (a one-line reframe that loops back to the hook); no 'endcard'",
  "every figure must cite a fact ref '<row fact_key>#<column>' from an llm.* view row and equal it",
  "highlight_player_id must be one of rows",
  "never use 'did you know' framing; hook_shape is one of payoff-first | contradiction | scenario | stake"
 ]
}

